// index.ts:531–541 — 唯一一处 setTimeout：abort 时 SIGTERM → 5s 后升级 SIGKILL
if (signal) {
    const killProc = () => {
        wasAborted = true;
        proc.kill("SIGTERM");
        setTimeout(() => {
            if (!proc.killed) proc.kill("SIGKILL");
        }, 5000);
    };
    if (signal.aborted) killProc();
    else signal.addEventListener("abort", killProc, { once: true });
}

// index.ts:183–184 — 失败判定
function isFailedResult(result: SingleResult): boolean {
    return result.exitCode !== 0 || result.stopReason === "error" || result.stopReason === "aborted";
}

// index.ts:472–528 — 进程退出 / 错误事件
proc.on("close", (code) => { if (buffer.trim()) processLine(buffer); resolve(code ?? 0); });
proc.on("error", () => { resolve(1); });
// index.ts:544 — 把 abort 抛回上层
