  stdio: ["ignore", "pipe", "pipe"],
  detached: true,  // ← 新增：让子进程成为新进程组组长
});
```
- Windows 上 `detached: true` 在 Node.js 仍受支持（创建 Job Object），但 `process.kill(-pid, sig)` 在 Windows 上无效；处理见阶段 G

**7. 装看门狗**（紧跟 `proc.stdout.on("data", ...)` 之后）：
```ts
const IDLE_TIMEOUT_MS = 600_000;
let watchdog: NodeJS.Timeout | null = null;
let suspended = false;

const armWatchdog = () => {
  if (watchdog) clearTimeout(watchdog);
  watchdog = setTimeout(onIdle, IDLE_TIMEOUT_MS);
};

const onIdle = () => {
  if (suspended || proc.exitCode !== null) return;
  suspended = true;
  // 平台分支见阶段 G
  freezeProcessGroup(proc); // 内部：win32 → skip 直接走 kill；posix → process.kill(-proc.pid!, "SIGSTOP")
  const id = newSuspensionId();
  const suspension: Suspension = {
    id, proc, inFlight, messages: [...currentResult.messages],
    stderr: currentResult.stderr, invocation: invocation.args.join(" "),
    job: jobContext ?? { kind: "single", makeDetails, onUpdate, signal },
    partialResult: { ...currentResult },
    suspendedAtMs: Date.now(),
    pgid: proc.pid ?? -1,
    signalListenerDetached: false,
    originalSignal: signal,
    abortHandler: null,
  };
  detachSignalListener(suspension); // 阶段 D 详述
  registerSuspension(suspension);
  resolve({ __suspended: true, id } as const);
};

armWatchdog();
```

**8. 把"重置看门狗"埋进 processLine / stderr / close**：
- `processLine` 每次成功解析后 `armWatchdog();`
- `proc.stderr.on("data", ...)` 末尾 `armWatchdog();`
- `proc.on("close", code => { if (watchdog) clearTimeout(watchdog); ... })`

**9. resolve 签名改为 union**：
```ts
type RunOutcome = { kind: "exit"; code: number } | { kind: "suspended"; id: SuspensionId };
```
- `proc.on("close", code => { ... resolve({ kind: "exit", code: code ?? 0 }); })`
- `proc.on("error", () => { if (watchdog) clearTimeout(watchdog); resolve({ kind: "exit", code: 1 }); })`
- `onIdle` resolve `{ kind: "suspended", id }`
- `runSingleAgent` 整体返回 `Promise<{ outcome: RunOutcome; result: SingleResult }>`
- 后续 `wasAborted` 判断改为 `outcome.kind === "exit"` 路径上才用；`suspended` 路径不抛错、不修改 exitCode

**10. 修 finally 块**：tmp 文件清理照旧；watchdog 清理移到 close/error 分支，确保 suspended 路径下 watchdog 不误清

### 阶段 D · AbortSignal 生命周期修正

**11. 在 `suspensions.ts` 导出 `attachSignalListener` / `detachSignalListener`**：
```ts
export function attachSignalListener(
  signal: AbortSignal,
  proc: ChildProcess,
  onAbort: () => void,
): () => void {
  if (signal.aborted) { onAbort(); return () => {}; }
  signal.addEventListener("abort", onAbort, { once: true });
  return () => signal.removeEventListener("abort", onAbort);
}
```

**12. `onAbort` 改为智能版本**：
```ts
const onAbort = () => {
  if (suspended) return;          // 挂起中不响应 abort
  wasAborted = true;
  killProcessGroup(proc, "SIGTERM");
  setTimeout(() => {
    if (proc.exitCode === null && !proc.killed) {
      killProcessGroup(proc, "SIGKILL");
    }
  }, 5000);
};
```

**13. 现有 index.ts:531-541 的信号注册替换**：
```ts
const abortHandler = () => onAbort();
let detachSignal: (() => void) | null = null;
if (signal) detachSignal = attachSignalListener(signal, proc, abortHandler);
```
- 在 `onIdle` 内 `suspension.signalListenerDetached = true;` 之前调用 `detachSignal?.()`（如果存在）保存到 `suspension.abortHandler` 字段——这里 abortHandler 是"重新添加用"的版本，**不是**原来那个
- 实际设计：保存 `(reAttach) => void` 形式的闭包即可，suspensions.ts 提供 `reAttachAbortListener(suspension)`，内部用 `originalSignal` 重新 addEventListener

**14. 防止 race**：信号在 `suspended = true` 之前一刻 abort 触发 → `onAbort` 看到 `suspended === false` 走 SIGTERM；但紧接着 onIdle 触发 → SIGSTOP 已挂进程，SIGTERM 投递不到；为简化——onAbort 改成只在 watchdog 未启动时 kill（实际场景几乎不会发生，因为事件驱动）；或更稳的：用一个 `abortedRef` 标志位，suspend 后下一行 processLine 检查到 abort 标志就把 proc 当作 aborted 收尾。我们采用更简单的方案：`onAbort` 加 `if (suspended || proc.exitCode !== null) return;` 已经覆盖——SIGSTOP 后信号队列在内核层仍可能排队，但 SIGSTOP 已先；最终靠 SIGCONT（resume）或 SIGKILL（kill）清理

### 阶段 E · 平台分支（win32 降级）

**15. 在 `suspensions.ts` 顶部定义**：
```ts
import { spawn as nodeSpawn } from "node:child_process";

export function isPosixSuspendSupported(): boolean {
  return process.platform !== "win32";
}

export function freezeProcessGroup(proc: ChildProcess): void {
  if (!isPosixSuspendSupported() || proc.pid == null) return;
  // win32: no-op（已由调用方走替代路径——直接 kill 而非 suspend）
  try { process.kill(-proc.pid, "SIGSTOP"); } catch { /* 进程可能已退出 */ }
}

export function thawProcessGroup(proc: ChildProcess): void {
  if (!isPosixSuspendSupported() || proc.pid == null) return;
  try { process.kill(-proc.pid, "SIGCONT"); } catch {}
}

export function killProcessGroup(proc: ChildProcess, signal: NodeJS.Signals | "SIGKILL"): void {
  if (proc.pid == null) return;
  if (isPosixSuspendSupported()) {
    try { process.kill(-proc.pid, signal); } catch { try { proc.kill("SIGKILL"); } catch {} }
  } else {
    // win32: 用 taskkill /T /F 杀整棵进程树
    try {
      nodeSpawn("taskkill", ["/pid", String(proc.pid), "/T", "/F"], { stdio: "ignore" });
    } catch { try { proc.kill("SIGKILL"); } catch {} }
  }
}
```

**16. Windows 降级策略（理由写在代码注释）**：因为没有 SIGSTOP/SIGCONT，无法真"冻结"做裁决；降级为「看门狗触发 → 立即 kill 整个进程组 → 工具提前返回『aborted (idle timeout)』」，不进入 suspension registry。即：`onIdle` 内 `if (!isPosixSuspendSupported()) { killProcessGroup(proc, "SIGKILL"); resolve({ kind: "exit", code: 1 }); return; }`。这样 POSIX 路径上才有 resume/kill/inspect 协议；Windows 用户实际能拿到的"防冻结"保护来自阶段 A 的 300s bash timeout。

