**24. 在 `index.ts` 模块底部（export default 之外）注册 process hook**：
```ts
import { getAllSuspensions } from "./suspensions.ts";

function sweepOnExit() {
  for (const s of getAllSuspensions()) {
    try { process.kill(-s.pgid, "SIGCONT"); } catch {}
    try { process.kill(-s.pgid, "SIGKILL"); } catch {}
  }
}
process.on("exit", sweepOnExit);
process.on("SIGINT", () => { sweepOnExit(); process.exit(130); });
process.on("SIGTERM", () => { sweepOnExit(); process.exit(143); });
```
